create table public.supplier_contingency_plans(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,alternative_supplier text,procedure_text text not null check(length(trim(procedure_text)) between 20 and 10000),replacement_target_hours integer check(replacement_target_hours between 1 and 8760),emergency_contact text,last_validated_at date,next_review_at date,status text not null default 'DRAFT' check(status in('DRAFT','VALIDATED','EXPIRED')),created_at timestamptz not null default now(),created_by uuid references public.user_profiles(id) on delete set null,updated_at timestamptz not null default now(),updated_by uuid references public.user_profiles(id) on delete set null);
create trigger supplier_contingency_plans_updated before update on public.supplier_contingency_plans for each row execute function public.set_updated_at();
create index supplier_contingency_org_status_idx on public.supplier_contingency_plans(organization_id,status,next_review_at);
alter table public.supplier_contingency_plans enable row level security;
create policy "members read supplier contingency" on public.supplier_contingency_plans for select to authenticated using(public.is_organization_member(organization_id));
create policy "managers manage supplier contingency" on public.supplier_contingency_plans for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]));
